from scipy.optimize import minimize
input_data_str=sys.stdin.read()
data_list=json.loads(input_data_str)
outputs=np.array([row[0] for row in data_list])
P=np.array([row[1] for row in data_list])

def pred(params):
    r,K=params
    return -r * P * (1-P/K)

def loss(params):
    return np.mean((pred(params)-outputs)**2)

res=minimize(loss,[1.0,1.0])
print('opt',res.x,'mse',res.fun)
yp=pred(res.x)
print('MAPE',np.mean(np.abs((yp-outputs)/outputs)))
"}

