P = np.array([row[2] for row in data_list])
# logistic model

def logistic(params):
    r, K = params
    return r*P*(1-P/K)

def loss(params):
    pred = logistic(params)
    return np.mean((pred - outputs)**2)

# try multiple initial guesses
best=None
best_loss=1e9
for r0 in [0.01,0.05,0.1,0.5,1.0]:
    for K0 in [50,100,200,500,1000]:
